import {mountPlayerExplorer,stopPlayerExplorer} from './player-explorer-ui.mjs?v=2026-10-31.2';
export {stopPlayerExplorer};
import {findComparablePlayers} from './player-model.mjs?v=2026-10-31.2';
const state={playerId:null,teamId:null,targetId:null,search:'',external:null,request:0,opponentMatch:null,pending:false,identity:{}};
const idOf=p=>String(p?.playerId??p?.id??'');
const position=p=>({0:'Kaleci',1:'Defans',2:'Orta saha',3:'Forvet'})[p?.position]||'Mevki bilinmiyor';
const metric=(p,key,kind='sum')=>p?.metrics?.[key]?.[kind]??(kind==='sum'?p?.[key]:null);
const metricNames={minutes_played:'Oynanan dakika',rating_title:'FotMob puanı',rating:'FotMob puanı',goals:'Gol',assists:'Asist',expected_goals:'Beklenen gol (xG)',expected_assists:'Beklenen asist (xA)',xg_and_xa:'xG + xA',total_shots:'Şut',ShotsOnTarget:'İsabetli şut',accurate_passes:'İsabetli pas',chances_created:'Yaratılan fırsat',touches:'Topa dokunuş',touches_opp_box:'Rakip ceza sahasında dokunuş',defensive_actions:'Defansif hamle','matchstats.headers.tackles':'Top kapma',interceptions:'Pas arası',clearances:'Uzaklaştırma',recoveries:'Top kazanma',keeper_saves:'Kurtarış',goals_prevented:'Önlenen gol',aerials_won:'Hava mücadelesi',duel_won:'Kazanılan mücadele',physical_metrics_distance_covered:'Mesafe (m)',physical_metrics_topspeed:'En yüksek hız',physical_metrics_number_of_sprints:'Sprint sayısı',saves90:'Kurtarış / 90',goalsPrevented90:'Önlenen gol / 90',passes90:'İsabetli pas / 90',tackles90:'Top kapma / 90',interceptions90:'Pas arası / 90',defensiveActions90:'Defansif hamle / 90',keyPasses90:'Yaratılan fırsat / 90',xa90:'xA / 90',xg90:'xG / 90',goals90:'Gol / 90',shots90:'Şut / 90'};
const groups=[['starters','İlk 11'],['bench','Yedekler'],['unavailable','Kaynakta eksik'],['archive','Diğer geçmiş oyuncular']];
export function selectNetworkPlayer(id,teamId=null,identity={}){state.identity=identity;state.playerId=String(id);state.teamId=teamId==null?null:String(teamId);state.external=null;state.pending=true;state.opponentMatch=null;state.search='';}
function profile(a,id,teamId){if(teamId!=null)return a.byKey?.[`${teamId}:${id}`]??a.resolvePlayer?.(id,teamId,state.identity)??null;return a.byId?.[String(id)]??null;}
function initialPlayer(a,teamId){const ps=a.teams?.[String(teamId)]?.players??[];return ps.find(p=>p.rosterGroups?.includes('starters'))??ps.find(p=>p.rosterGroups?.includes('bench'))??ps[0];}
export function renderPlayers(root,ctx){
 const personal=root.querySelector('#player-personal-profile');if(personal)state.personalOpen=personal.open;
 stopPlayerExplorer();
 const {bundle,result,options,esc}=ctx,a=result.playerAnalysis;
 if(!a){root.innerHTML='<p class="empty">Oyuncu katmanı hazırlanıyor.</p>';return;}
 if(state.targetId!==String(bundle.target.id)){if(!state.pending){state.playerId=null;state.teamId=String(bundle.target.home.id);state.external=null;}state.targetId=String(bundle.target.id);}
 state.pending=false;
 const requested=new URLSearchParams(location.search).get('player');if(!state.playerId&&requested&&a.byId?.[requested]){state.playerId=requested;state.teamId=String(a.byId[requested].teamId);}
 let selected=state.external??(state.playerId?profile(a,state.playerId,state.teamId):initialPlayer(a,state.teamId??bundle.target.home.id)??a.profiles?.[0]);
 if(!selected&&state.playerId)selected={id:state.playerId,playerId:state.playerId,name:state.identity.name??'Oyuncu '+state.playerId,teamId:state.teamId,teamName:state.identity.teamName??a.teams?.[state.teamId]?.name??'Takım bağlamı arşivde yok',position:state.identity.position??null,matches:[],metrics:{},games:0,minutes:0,historyCoverage:{status:'partial',reason:'player-context-unavailable',selected:0,withDetails:0}};
 if(selected){state.playerId=idOf(selected);if(selected.teamId!=null)state.teamId=String(selected.teamId);}
 state.teamId??=String(bundle.target.home.id);
 const roots=[String(bundle.target.home.id),String(bundle.target.away.id)];
 const teams=Object.values(a.teams??{}).sort((x,y)=>{const ix=roots.indexOf(String(x.id)),iy=roots.indexOf(String(y.id));return (ix<0?2:ix)-(iy<0?2:iy)||String(x.name).localeCompare(String(y.name),'tr');});
 if(!teams.some(t=>String(t.id)===state.teamId))teams.push({id:state.teamId,name:selected?.teamName??'Takım bağlamı arşivde yok'});
 root.innerHTML=`<div class="section-heading"><h2>Oyuncuların bağlantı haritası.</h2><button class="button primary" data-view="simulation">Kadroları çarpıştır ▶</button><span class="tag">SON ${options.formCount} OYNADIĞI MAÇ</span></div><p class="section-desc">Oyuncunun süre aldığı son ${options.formCount} resmî karşılaşma, eski takımlarındaki performanslarıyla birlikte incelenir. Takımın son ${options.formCount} maçındaki katkısı ayrıca gösterilir. Eksik veriler sıfır sayılmaz.</p><div id="player-explorer"></div><div class="player-effect card"><label><input type="checkbox" id="player-layer" ${options.playerLayer!==false?'checked':''}> Mevcut oyuncu katmanını tahmine kat</label><div>${ctx.result.training?.gbdt?.active?"İlk 11’in detaylı performansı GBDT girdisi olarak öğrenilir.":effectSummary(a,ctx)}</div><p class="inline-note">${ctx.result.training?.gbdt?.active?"GBDT etkin olduğunda eski ±%8 oyuncu çarpanı eklenmez. Oyuncu katmanını kapatmak takım modeline döner.":"Bu etki takım penceresindeki kadro dağılımından gelir ve ±%8 ile sınırlıdır."} Yeni lig puanı açıklayıcı karşılaştırmadır; ayrıca gol olasılığına eklenmez.</p></div><form id="player-link-form" class="player-link"><label for="player-link">FotMob oyuncusu</label><input id="player-link" class="filter-input" placeholder="FotMob oyuncu bağlantısı veya kimliği"><button class="button ghost">Profili aç ↗</button></form><div id="player-message" class="inline-note" role="status"></div><details id="player-personal-profile" class="player-personal-profile" ${state.personalOpen?'open':''}><summary>Ayrıntılı oyuncu profili, kadro ve sezon verisi</summary><div class="player-layout"><section class="card player-roster"><div class="card-title"><h2>Takımın oyuncuları</h2><span class="tag">KADRO & GEÇMİŞ</span></div><label class="small-text" for="player-team">Takım</label><select id="player-team" class="filter-input">${teams.map(t=>`<option value="${t.id}" ${String(t.id)===state.teamId?'selected':''}>${esc(t.name)}${String(t.id)===roots[0]?' · Ev sahibi':String(t.id)===roots[1]?' · Deplasman':''}</option>`).join('')}</select><label class="small-text spaced" for="player-search">Oyuncu ara</label><input class="filter-input" id="player-search" placeholder="Oyuncu adı…" value="${esc(state.search)}"><div id="player-roster-list"></div></section><section id="player-detail" class="player-detail"></section></div></details>`;
 root.querySelector('#player-layer').onchange=e=>{options.playerLayer=e.target.checked;ctx.recalculate();};
 root.querySelector('#player-team').onchange=e=>{state.teamId=e.target.value;state.search='';state.playerId=null;state.external=null;state.opponentMatch=null;renderPlayers(root,ctx);};
 root.querySelector('#player-search').oninput=e=>{state.search=e.target.value;roster(root,ctx);};
 root.querySelector('#player-link-form').onsubmit=e=>{e.preventDefault();const input=root.querySelector('#player-link').value.trim();let id;if(/^\d{4,12}$/.test(input))id=input;else try{const u=new URL(input);if(['http:','https:'].includes(u.protocol)&&/(^|\.)fotmob\.com$/i.test(u.hostname))id=u.pathname.match(/\/(?:[a-z-]+\/)?players\/(\d{4,12})(?:\/|$)/)?.[1];}catch{}if(!id){root.querySelector('#player-message').textContent='Geçerli FotMob oyuncu bağlantısı veya oyuncu kimliği girin.';return;}if(a.byId?.[id])selectNetworkPlayer(id);else state.external={id,name:'Oyuncu '+id,teamId:null,matches:[],metrics:{},historyCoverage:{status:'archive-only',selected:0}};renderPlayers(root,ctx);};
 root.onclick=e=>{const s=e.target.closest('[data-select-player]');if(s){selectNetworkPlayer(s.dataset.selectPlayer,s.dataset.selectTeam,{name:s.dataset.selectName,teamName:s.dataset.selectTeamName});renderPlayers(root,ctx);return;}const m=e.target.closest('[data-opponents-for]');if(m){state.opponentMatch=m.dataset.opponentsFor;if(selected)opponents(root,selected,ctx);}};
 root.onkeydown=e=>{if(!['Enter',' '].includes(e.key))return;const m=e.target.closest('.player-match-node');if(m){e.preventDefault();ctx.openMatch(m.dataset.match);}const o=e.target.closest('[data-opponents-for]');if(o&&o.tagName.toLowerCase()!=='button'){e.preventDefault();state.opponentMatch=o.dataset.opponentsFor;if(selected)opponents(root,selected,ctx);}};
 roster(root,ctx);if(selected)detail(root,selected,ctx);else root.querySelector('#player-detail').innerHTML='<p class="empty">Bu takımda kayıtlı oyuncu yok.</p>';
 mountPlayerExplorer(root.querySelector('#player-explorer'),ctx,selected,(id,teamId,node)=>{selectNetworkPlayer(id,teamId,{name:node.name,teamName:node.teamName,position:node.position});renderPlayers(root,ctx);state.personalOpen=true;root.querySelector('#player-personal-profile').open=true;root.querySelector('#player-detail')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});
}
function effectSummary(a,{bundle,number,esc}){return ['home','away'].map(side=>`<span>${esc(bundle.target[side].name)}: <b>${number(((a.adjustments?.[side]?.factor??1)-1)*100,2)}%</b></span>`).join('')+`<small>${esc(a.adjustments?.home?.reason??'Kadro ve geçmiş kapsamına göre hesaplanır.')}</small>`;}
function roster(root,ctx){
 const {result,esc,number,bundle}=ctx,a=result.playerAnalysis,team=a.teams?.[state.teamId],players=(team?.players??[]).filter(p=>String(p.name).toLocaleLowerCase('tr').includes(state.search.toLocaleLowerCase('tr')));
 const row=p=>{const rating=a.leagueRatings?.byId?.[idOf(p)];return `<button class="player-row ${idOf(p)===state.playerId?'selected':''}" data-select-player="${idOf(p)}" data-select-team="${p.teamId}" data-select-name="${esc(p.name)}" data-select-team-name="${esc(p.teamName??team?.name??'')}"><img src="https://images.fotmob.com/image_resources/playerimages/${idOf(p)}.png" alt="" loading="lazy" width="34" height="34" onerror="this.style.visibility='hidden'"><span><b>${esc(p.name)}</b><small>${position(p)} · ${number(p.minutes,0)} dk · ${p.games??0} maç${p.rosterGroups?.includes('unavailable')?' · Kaynakta eksik':''}</small></span><strong>${number(rating?.score,0)}<small>LİG / 100</small></strong></button>`;};
 const reference=bundle.targetLineup?.type==='lastStarting11';
 root.querySelector('#player-roster-list').innerHTML=players.length?groups.map(([key,title])=>{const ps=players.filter(p=>(p.rosterGroups?.length?p.rosterGroups:['archive']).includes(key));return ps.length?`<section class="roster-group" data-roster-group="${key}"><h3>${title}${key==='starters'&&reference?' · son maç referansı':''}<span>${ps.length}</span></h3>${ps.map(row).join('')}</section>`:'';}).join(''):'<p class="empty">Oyuncu bulunamadı.</p>';
}
function historyNote(p,n){
 const h=p.historyCoverage??{},kept=h.retainedFromPrevious?` Önceki kayıttan ${h.retainedMatchIds?.length??0} maç korundu; bu sorguda yenilenemedi.`:'';
 if(h.status==='archive-only')return `Arşivde bulunan ${p.games??0} performans. Oyuncunun kendi son ${n} maçının tamamı doğrulanmadı.`;
 if(h.status==='complete')return `Son ${n} oynanmış maç seçildi; ${h.withDetails??p.games??0} maçın ayrıntısı mevcut.`;
 if(h.status==='exhausted')return `Kaynakta ${h.selected??p.games??0} oynanmış maç bulundu; istenen dönem ${n} maç.`;
 const reasons={'missing-minutes':'Bazı maçlarda süre bilgisi eksik.','detail-unavailable':'Bazı maçların ayrıntıları eksik.','player-statistics-missing':'Bazı maçların oyuncu istatistikleri eksik.','match-identity-mismatch':'Bazı maçların takım bilgileri kaynaklar arasında uyuşmuyor.','player-context-unavailable':'Oyuncunun bu takımdaki geçmişi arşivde doğrulanamadı.','cutoff-mismatch':'Kayıtların zaman kapsamı bu analizle eşleşmiyor.','time-budget':'Geçmişin tamamı bu sorguda alınamadı.','page-budget':'Geçmişin tamamı bu sorguda alınamadı.'};
 return `Seçilen ${h.selected??p.games??0}/${n} maç; ayrıntısı mevcut ${h.withDetails??0}. ${reasons[h.reason]??'Kaynak yanıtı nedeniyle geçmiş tamamlanamadı.'}${kept}`;
}
function detail(root,p,ctx){
 const {bundle,result,options,esc,number,date,pct}=ctx,a=result.playerAnalysis,id=idOf(p),teamName=p.teamName??a.teams?.[String(p.teamId)]?.name??'Arşiv dışında';
 const similar=findComparablePlayers(a,p).slice(0,5),tc=p.teamContribution,base=result.baselinePrediction,pred=result.playerPrediction??result.prediction;
 const status=p.rosterGroups?.includes('unavailable')?'Kaynakta eksik':p.rosterGroups?.includes('starters')?bundle.targetLineup?.type==='confirmed'?'Doğrulanmış ilk 11':'Kaynak ilk 11 referansı':p.rosterGroups?.includes('bench')?'Yedek listesinde':'Geçmiş performans';
 root.querySelector('#player-detail').innerHTML=`<article class="card player-profile"><div class="player-profile-heading"><img src="https://images.fotmob.com/image_resources/playerimages/${id}.png" alt="${esc(p.name)}" width="74" height="74" onerror="this.style.visibility='hidden'"><div><div class="eyebrow">${esc(teamName)} · ${position(p)}</div><h2>${esc(p.name)}</h2><p class="inline-note">${status}${bundle.targetLineup?.type==='lastStarting11'?' · Son maçtaki kadro, bu maçın kesin kadrosu değildir.':''}</p></div></div><h3>Kendi son ${options.formCount} oynadığı maç</h3><div class="mini-stats"><div><b>${number(metric(p,'goals'),0)}</b><span>GOL</span></div><div><b>${number(metric(p,'assists'),0)}</b><span>ASİST</span></div><div><b>${number(p.xg90,2)}</b><span>xG / 90</span></div></div><p class="inline-note player-history-coverage">${esc(historyNote(p,options.formCount))}</p><div class="player-team-contribution"><h3>Takımın son ${options.formCount} maçındaki katkısı</h3><p>${tc?.games??0} maç · ${number(tc?.minutes??0,0)} dakika · ${number(metric(tc,'goals'),0)} gol · ${number(metric(tc,'assists'),0)} asist</p><p class="inline-note">Yalnız ${esc(teamName)} form penceresi. Transfer öncesi maçlar bu katkıya eklenmez.</p></div><div class="player-scenario"><label for="player-availability">Kadro senaryosu</label><select id="player-availability"><option value="auto">Kaynak kadroyu kullan</option><option value="out">Bu oyuncu yok varsay</option><option value="in">Bu oyuncu var varsay</option></select><p class="inline-note">Var/yok seçimi sizin varsayımınızdır; kadro haberi olarak kaydedilmez.</p></div><div class="player-baseline"><span>Takım modeli: <b>${number(base?.homeXg,3)} – ${number(base?.awayXg,3)} gol</b></span><span>Mevcut oyuncu katmanıyla: <b>${number(pred?.homeXg,3)} – ${number(pred?.awayXg,3)} gol</b></span></div></article>${ratingCard(p,ctx)}<article class="card spaced"><h2>Benzer bireysel profiller</h2>${similar.length?similar.map(s=>`<button class="similar-player" data-select-player="${s.playerId??s.id}" data-select-team="${s.teamId}" data-select-name="${esc(s.name)}" data-select-team-name="${esc(s.teamName??'')}"><b>${esc(s.name)}</b><span>${esc(s.teamName??a.teams?.[String(s.teamId)]?.name??'')} · ${pct(s.similarity)} benzerlik</span></button>`).join(''):'<p class="inline-note">Yeterli dakika ve ortak ölçüm bulunan aynı mevkide profil yok.</p>'}</article><article class="card spaced"><div class="card-title"><h2>Kişisel formun tüm ölçümleri</h2><button class="text-button" id="player-export">Oyuncu JSON ↓</button></div><div class="table-wrap"><table><thead><tr><th>METRİK</th><th>TOPLAM</th><th>MAÇ BAŞI</th><th>90 DK</th><th>KAPSAM</th></tr></thead><tbody>${Object.entries(p.metrics??{}).map(([k,v])=>`<tr><td>${esc(metricNames[k]??bundle.playerMetricInventory?.find(m=>m.key===k)?.title??k)}</td><td>${number(v.sum,2)}</td><td>${number(v.average,2)}</td><td>${number(v.per90,2)}</td><td>${v.games??0}/${p.games??0} maç</td></tr>`).join('')}</tbody></table></div><p class="inline-note">Eksikler sıfır sayılmaz. FotMob puanı ve yüzde gibi ölçümler toplanmaz veya 90 dakikaya çevrilmez.</p></article><article class="card spaced"><h2>Kendi maç geçmişi</h2><div class="table-wrap"><table><thead><tr><th>TARİH</th><th>OYNADIĞI TAKIM</th><th>RAKİP</th><th>SKOR</th><th>DAKİKA</th><th>KAYIT</th></tr></thead><tbody>${(p.matches??[]).map(m=>`<tr><td>${date(m.date)}</td><td>${esc(m.playedForTeam?.name??m.teamName??'—')}</td><td><button data-match="${m.matchId??m.id}">${esc(m.opponent?.name??'Maç')}</button></td><td>${esc(m.score??'—')}</td><td>${number(m.minutes,0)}</td><td>${m.detailStatus==='unavailable'?'Ayrıntı eksik':'Maç ayrıntısı'}</td></tr>`).join('')}</tbody></table></div></article><article class="card spaced" id="player-source-profile"><h2>FotMob oyuncu profili</h2><p class="inline-note">Güncel kaynak profili yükleniyor…</p></article>`;
 const select=root.querySelector('#player-availability');select.value=options.playerScenarios?.[id]??'auto';select.disabled=!tc?.games;select.onchange=()=>{options.playerScenarios??={};if(select.value==='auto')delete options.playerScenarios[id];else options.playerScenarios[id]=select.value;ctx.recalculate();};
 root.querySelector('#player-export').onclick=()=>ctx.download('mathgoal-player-'+id+'.json',{...p,leagueRating:a.leagueRatings?.byId?.[id]??null,leagueCoverage:a.leagueRatings?.coverage??null});
 opponents(root,p,ctx);fetchProfile(root,id,ctx);
}
function ratingCard(p,{bundle,result,esc,number}){
 const league=result.playerAnalysis.leagueRatings,r=league?.byId?.[idOf(p)],coverage=league?.coverage;
 const reasons={'insufficient-appearances':'En az 3 maç ve 180 dakika gerekiyor.','unknown-position':'Mevki bilgisi yetersiz.','insufficient-dimensions':'En az 3 ölçümde, en az 5 uygun referans oyuncusu gerekiyor.'};
 return `<article class="card spaced player-rating"><div class="card-title"><h2>MathGoal lig puanı</h2><span class="tag">AYNI LİG · AYNI MEVKİ</span></div><div class="rating-heading"><strong>${number(r?.score,1)}<small>/ 100</small></strong><div>${esc(bundle.target.leagueName??(league?.leagueId?'Lig '+league.leagueId:'Lig bilinmiyor'))} · ${esc(league?.season??'Sezon doğrulanmadı')}<p class="inline-note">${r?.score!=null?`${r.metricCount}/${r.totalMetrics} ölçüm · ${r.games} lig maçı · ${number(r.minutes,0)} dakika`:esc(reasons[r?.reason]??'Bu oyuncu için doğrulanmış lig/sezon referansı yok.')}</p></div></div><p class="inline-note">${coverage?.status==='complete'?`${coverage.withPlayerStats}/${coverage.expected} uygun lig maçında oyuncu verisi mevcut.`:coverage?.status==='partial'?`Eldeki lig verisine göre: ${coverage.withPlayerStats}/${coverage.expected} maç. Eksik sezon kapsamı var.`:'Lig sezonunun fikstür kapsamı doğrulanmadığı için puan hesaplanmadı.'}</p>${r?.components?.length?`<details><summary>Puanın dayanakları</summary><div class="table-wrap"><table><thead><tr><th>ÖLÇÜM</th><th>DEĞER</th><th>LİG YÜZDELİĞİ</th><th>REFERANS</th></tr></thead><tbody>${r.components.map(c=>`<tr><td>${esc(metricNames[c.key]??c.key)}</td><td>${number(c.value,2)}</td><td>${number(c.percentile,1)}</td><td>${c.referenceCount} oyuncu${c.reason?' · yetersiz kapsam':''}</td></tr>`).join('')}</tbody></table></div></details>`:''}<p class="inline-note">Uygun metriklerin mevki içi yüzdelikleri eşit ağırlıkla ortalanır. Farklı ölçüm kapsamındaki puanlar aynı kapsamda değildir. Bu puan maç sonucu olasılığı veya ligler arası mutlak güç değildir.</p></article>`;
}
function playerGraph(p,{esc,date}){
 const rows=p.matches??[],h=Math.max(220,rows.length*48+55),cy=h/2;
 return `<svg viewBox="0 0 1000 ${h}" role="group" aria-label="${esc(p.name)} oyuncusunun maç ve rakip oyuncu ağı"><circle cx="140" cy="${cy}" r="48" fill="#2b3b24" stroke="#c3ef79"/><text x="140" y="${cy+4}" text-anchor="middle" fill="#c3ef79" font-size="11">${esc(p.name)}</text>${rows.map((m,i)=>{const y=30+i*48,id=m.matchId??m.id;return `<line x1="188" y1="${cy}" x2="500" y2="${y}" stroke="#779966" opacity=".35"/><line x1="520" y1="${y}" x2="760" y2="${y}" stroke="#c49b70" opacity=".45"/><g class="player-match-node" role="button" tabindex="0" data-match="${id}" aria-label="${date(m.date)} ${esc(m.opponent?.name)} maç ayrıntısı"><rect x="390" y="${y-20}" width="145" height="40" fill="transparent"/><circle cx="510" cy="${y}" r="16" fill="#293c26" stroke="#90b775"/><text x="510" y="${y+4}" text-anchor="middle" fill="#d2e6bd" font-size="9">${esc(m.score??'—')}</text><text x="477" y="${y+4}" text-anchor="end" fill="#92a98a" font-size="10">${date(m.date)}</text></g><g class="opponent-node" role="button" tabindex="0" data-opponents-for="${id}" aria-label="${esc(m.opponent?.name)} rakip oyuncularını göster"><rect x="750" y="${y-20}" width="240" height="40" fill="transparent"/><circle cx="770" cy="${y}" r="12" fill="#6d4b2f" stroke="#d6a479"/><text x="790" y="${y-2}" fill="#d6b99b" font-size="11">${esc(m.opponent?.name??'Rakip')}</text><text x="790" y="${y+13}" fill="#a98b70" font-size="9">${m.opponentPlayers?.length??0} süre alan oyuncu →</text></g>`;}).join('')}</svg>`;
}
function opponents(root,p,{esc,number,date}){
 const rows=p.matches??[],m=rows.find(x=>String(x.matchId??x.id)===String(state.opponentMatch))??rows[0],box=root.querySelector('#player-opponents');if(!box)return;
 if(!m){box.innerHTML='<p class="inline-note">Oyuncunun oynanmış maç kaydı yok.</p>';return;}
 state.opponentMatch=String(m.matchId??m.id);
 box.innerHTML=`<div class="opponent-panel"><h3>${esc(m.opponent?.name??'Rakip')} · ${date(m.date)}</h3><p class="inline-note">Bu maçta süre aldığı doğrulanan rakip futbolcular. Oyuncuya tıklayarak kendi geçmişini inceleyin.</p><div class="pill-row">${(m.opponentPlayers??[]).map(q=>`<button class="select-pill" data-select-player="${q.playerId??q.id}" data-select-team="${q.teamId}" data-select-name="${esc(q.name)}" data-select-team-name="${esc(q.teamName??'')}">${esc(q.name)} <small>${number(q.minutes,0)} dk</small></button>`).join('')||'<span class="inline-note">Rakip oyuncuların maç verisi bu arşivde bulunamadı.</span>'}</div></div>`;
}
async function fetchProfile(root,id,ctx){const request=++state.request;try{const r=await fetch('/api/player?id='+encodeURIComponent(id));if(!r.ok)throw Error('Oyuncu profili alınamadı.');const snapshot=await r.json();if(request!==state.request)return;const {esc,number,date,download}=ctx,p=snapshot.data,box=root.querySelector('#player-source-profile');if(!box)return;box.innerHTML=`<div class="card-title"><h2>${esc(p.name)} · Güncel FotMob profili</h2><button class="text-button" id="source-player-download">Tam kaynak JSON ↓</button></div><p class="inline-note">${date(snapshot.observedAt)} · ${esc(p.mainLeague?.leagueName??'')} ${esc(p.mainLeague?.season??'')} · Kaynak sezon toplamları; geçmiş tahminlere aktarılmaz.</p><div class="mini-stats">${(p.mainLeague?.stats||[]).slice(0,6).map(s=>`<div><b>${number(Number(s.value),s.localizedTitleId==='rating'?2:0)}</b><span>${esc(metricNames[s.localizedTitleId]||s.title)}</span></div>`).join('')}</div>${(p.firstSeasonStats?.statsSection?.items||[]).map(group=>`<details class="stat-group"><summary>${esc(group.title)}</summary><div class="table-wrap"><table><thead><tr><th>ÖLÇÜM</th><th>SEZON TOPLAMI</th><th>90 DK / ORAN</th></tr></thead><tbody>${(group.items||[]).map(s=>`<tr><td>${esc(metricNames[s.localizedTitleId]||s.title)}</td><td>${esc(s.statValue??'—')}${s.statFormat==='percent'?'%':''}</td><td>${number(s.per90,2)}${s.statFormat==='percent'?'%':''}</td></tr>`).join('')}</tbody></table></div></details>`).join('')}<p class="inline-note">Şut haritası: ${p.firstSeasonStats?.shotmap?.length??0} şut. Özellik yüzdelikleri, kariyer, sakatlık, sözleşme ve diğer alanlar tam kaynak JSON içindedir.</p><a class="text-button" href="${esc(snapshot.source)}" target="_blank" rel="noreferrer">FotMob oyuncu sayfası ↗</a>`;box.querySelector('#source-player-download').onclick=()=>download('fotmob-player-'+id+'.json',snapshot);}catch(e){if(request!==state.request)return;const box=root.querySelector('#player-source-profile');if(box)box.innerHTML='<p class="inline-note">'+ctx.esc(e.message)+' Maç bazlı arşiv verileri yukarıda kullanılabilir.</p>';}}
